use crate::aap::caps::kb_read;

struct Node;

/// Matches the `ensures len(question) <= 512` contract (counted in characters,
/// as Python's `len` does).
const MAX_QUESTION_CHARS: usize = 512;

/// Sentinel so that `ensures present(knowledge)` holds when the store has no match.
const NO_MATCH: &str = "No knowledge-base entries matched this question.";

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let question: String = query
            .query
            .question
            .chars()
            .take(MAX_QUESTION_CHARS)
            .collect();

        let mut knowledge = kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(NO_MATCH.to_string());
        }

        ConversationContext {
            intent: query.query.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

